import sensor from '@system.sensor';
import { SENSOR_CONFIG } from '../constants';

// 传感器管理器
class SensorManager {
  constructor() {
    this.isRunning = false;
    this.dataBuffer = [];
    this.batchSize = SENSOR_CONFIG.batchSize;
    this.onDataCallback = null;
    this.onErrorCallback = null;
  }

  /**
   * 开始订阅传感器
   * @param {Function} onData - 数据回调
   * @param {Function} onError - 错误回调
   */
  start(onData, onError) {
    if (this.isRunning) {
      console.log('Sensor is already running');
      return;
    }

    this.onDataCallback = onData;
    this.onErrorCallback = onError;
    this.isRunning = true;
    this.dataBuffer = [];

    sensor.subscribe({
      sensorType: 'accelerometer',
      interval: SENSOR_CONFIG.interval,
      success: (data) => {
        this.handleSensorData(data);
      },
      fail: (data, code) => {
        console.error('Sensor subscribe failed:', code);
        if (this.onErrorCallback) {
          this.onErrorCallback(data, code);
        }
      }
    });

    console.log('Sensor started with interval:', SENSOR_CONFIG.interval, 'ms');
  }

  /**
   * 处理传感器数据
   * @param {Object} data - 传感器数据
   */
  handleSensorData(data) {
    const sensorData = {
      x: data.x || 0,
      y: data.y || 0,
      z: data.z || 0,
      timestamp: Date.now()
    };

    this.dataBuffer.push(sensorData);

    // 达到批量大小时处理数据
    if (this.dataBuffer.length >= this.batchSize) {
      const batchData = this.dataBuffer.splice(0, this.batchSize);
      if (this.onDataCallback) {
        this.onDataCallback(batchData);
      }
    }
  }

  /**
   * 停止订阅传感器
   */
  stop() {
    if (!this.isRunning) {
      console.log('Sensor is not running');
      return;
    }

    sensor.unsubscribe({
      sensorType: 'accelerometer'
    });

    this.isRunning = false;
    this.dataBuffer = [];
    this.onDataCallback = null;
    this.onErrorCallback = null;

    console.log('Sensor stopped');
  }

  /**
   * 获取当前缓冲区数据
   * @returns {Array} 缓冲区数据
   */
  getBufferData() {
    return [...this.dataBuffer];
  }

  /**
   * 清空缓冲区
   */
  clearBuffer() {
    this.dataBuffer = [];
  }
}

// 创建单例实例
const sensorManager = new SensorManager();

export default sensorManager;

import { POSTURE_TYPES, POSTURE_THRESHOLDS } from '../constants';

// 体态识别AI引擎
class PostureAIEngine {
  constructor() {
    this.windowSize = 50;  // 滑动窗口大小（样本数）
    this.dataWindow = [];
    this.currentPosture = POSTURE_TYPES.NORMAL;
    this.postureStartTime = Date.now();
    this.lastPosture = POSTURE_TYPES.NORMAL;
  }

  /**
   * 处理传感器数据批次
   * @param {Array} batchData - 批量传感器数据
   * @returns {Object} 识别结果
   */
  processBatch(batchData) {
    // 添加到滑动窗口
    this.dataWindow.push(...batchData);

    // 保持窗口大小
    if (this.dataWindow.length > this.windowSize) {
      this.dataWindow = this.dataWindow.slice(-this.windowSize);
    }

    // 数据不足时返回正常
    if (this.dataWindow.length < 10) {
      return {
        type: POSTURE_TYPES.NORMAL,
        confidence: 0.5,
        features: null
      };
    }

    // 提取特征
    const features = this.extractFeatures();

    // 分类体态
    const result = this.classifyPosture(features);

    // 更新状态
    this.updatePostureState(result);

    return {
      ...result,
      features
    };
  }

  /**
   * 提取特征
   * @returns {Object} 特征对象
   */
  extractFeatures() {
    const window = this.dataWindow;
    const n = window.length;

    // 计算平均值
    const avgX = window.reduce((sum, d) => sum + d.x, 0) / n;
    const avgY = window.reduce((sum, d) => sum + d.y, 0) / n;
    const avgZ = window.reduce((sum, d) => sum + d.z, 0) / n;

    // 计算方差
    const varX = window.reduce((sum, d) => sum + Math.pow(d.x - avgX, 2), 0) / n;
    const varY = window.reduce((sum, d) => sum + Math.pow(d.y - avgY, 2), 0) / n;
    const varZ = window.reduce((sum, d) => sum + Math.pow(d.z - avgZ, 2), 0) / n;

    // 计算姿态角（使用加速度计估算）
    const pitch = this.calculatePitch(avgX, avgY, avgZ);
    const roll = this.calculateRoll(avgX, avgY, avgZ);

    // 计算稳定性（方差越小越稳定）
    const totalVariance = varX + varY + varZ;
    const stability = Math.max(0, 1 - totalVariance * 10);

    // 计算运动幅度
    const amplitude = Math.sqrt(varX + varY + varZ);

    return {
      avgX,
      avgY,
      avgZ,
      varX,
      varY,
      varZ,
      pitch,
      roll,
      stability,
      amplitude
    };
  }

  /**
   * 计算俯仰角（Pitch）
   * @param {number} ax - X轴加速度
   * @param {number} ay - Y轴加速度
   * @param {number} az - Z轴加速度
   * @returns {number} 俯仰角（度）
   */
  calculatePitch(ax, ay, az) {
    // 使用加速度计估算俯仰角
    const pitch = Math.atan2(ax, Math.sqrt(ay * ay + az * az)) * (180 / Math.PI);
    return Math.abs(pitch);  // 返回绝对值
  }

  /**
   * 计算横滚角（Roll）
   * @param {number} ax - X轴加速度
   * @param {number} ay - Y轴加速度
   * @param {number} az - Z轴加速度
   * @returns {number} 横滚角（度）
   */
  calculateRoll(ax, ay, az) {
    const roll = Math.atan2(ay, Math.sqrt(ax * ax + az * az)) * (180 / Math.PI);
    return Math.abs(roll);  // 返回绝对值
  }

  /**
   * 分类体态
   * @param {Object} features - 特征对象
   * @returns {Object} 分类结果
   */
  classifyPosture(features) {
    const { pitch, roll, stability, amplitude } = features;
    const thresholds = POSTURE_THRESHOLDS;

    let type = POSTURE_TYPES.NORMAL;
    let confidence = 0.5;

    // 规则1: 低头前倾
    if (pitch > thresholds.pitch.headDown) {
      type = POSTURE_TYPES.HEAD_DOWN;
      confidence = Math.min(0.95, 0.85 + (pitch - thresholds.pitch.headDown) / 100);
    }
    // 规则2: 驼背弯腰
    else if (pitch > thresholds.pitch.hunchback) {
      type = POSTURE_TYPES.HUNCHBACK;
      confidence = Math.min(0.9, 0.8 + (pitch - thresholds.pitch.hunchback) / 100);
    }
    // 规则3: 左右倾斜
    else if (roll > thresholds.roll.tilt) {
      type = POSTURE_TYPES.TILT;
      confidence = Math.min(0.9, 0.8 + (roll - thresholds.roll.tilt) / 100);
    }
    // 规则4: 频繁晃动
    else if (stability < thresholds.stability.shake) {
      type = POSTURE_TYPES.SHAKE;
      confidence = Math.min(0.85, 0.75 + (thresholds.stability.shake - stability));
    }
    // 规则5: 正常坐姿
    else {
      type = POSTURE_TYPES.NORMAL;
      confidence = Math.min(0.95, 0.9 + stability * 0.05);
    }

    return {
      type,
      confidence,
      pitch,
      roll,
      stability
    };
  }

  /**
   * 更新体态状态
   * @param {Object} result - 分类结果
   */
  updatePostureState(result) {
    const now = Date.now();

    if (result.type === this.currentPosture) {
      // 体态未变化，继续计时
      return;
    }

    // 体态发生变化
    const duration = now - this.postureStartTime;

    // 记录之前的体态
    this.lastPosture = this.currentPosture;
    this.lastPostureDuration = duration;

    // 更新当前体态
    this.currentPosture = result.type;
    this.postureStartTime = now;
  }

  /**
   * 获取当前体态持续时间
   * @returns {number} 持续时间（毫秒）
   */
  getCurrentDuration() {
    return Date.now() - this.postureStartTime;
  }

  /**
   * 检查是否需要提醒
   * @returns {Object|null} 提醒信息
   */
  checkReminder() {
    const duration = this.getCurrentDuration();
    const thresholds = POSTURE_THRESHOLDS.duration;

    // 检查各类体态的持续时间
    if (this.currentPosture === POSTURE_TYPES.HEAD_DOWN &&
        duration >= thresholds.headDown) {
      return {
        type: this.currentPosture,
        duration,
        message: '检测到低头前倾，请抬头活动颈椎'
      };
    }

    if (this.currentPosture === POSTURE_TYPES.HUNCHBACK &&
        duration >= thresholds.hunchback) {
      return {
        type: this.currentPosture,
        duration,
        message: '检测到驼背弯腰，请挺直腰背'
      };
    }

    if (this.currentPosture === POSTURE_TYPES.TILT &&
        duration >= thresholds.tilt) {
      return {
        type: this.currentPosture,
        duration,
        message: '检测到左右倾斜，请保持身体平衡'
      };
    }

    if (this.currentPosture === POSTURE_TYPES.SHAKE &&
        duration >= thresholds.shake) {
      return {
        type: this.currentPosture,
        duration,
        message: '检测到频繁晃动，请保持稳定坐姿'
      };
    }

    return null;
  }

  /**
   * 获取当前体态信息
   * @returns {Object} 体态信息
   */
  getCurrentPostureInfo() {
    return {
      type: this.currentPosture,
      duration: this.getCurrentDuration(),
      lastType: this.lastPosture,
      lastDuration: this.lastPostureDuration || 0
    };
  }

  /**
   * 重置引擎状态
   */
  reset() {
    this.dataWindow = [];
    this.currentPosture = POSTURE_TYPES.NORMAL;
    this.postureStartTime = Date.now();
    this.lastPosture = POSTURE_TYPES.NORMAL;
    this.lastPostureDuration = 0;
  }
}

