const postureAI = new PostureAIEngine();

export default postureAI;

import storage from '@system.storage';
import { STORAGE_KEYS } from '../constants';

// 存储管理器
class StorageManager {
  /**
   * 保存数据
   * @param {string} key - 存储键
   * @param {*} value - 存储值
   * @returns {Promise} 保存结果
   */
  save(key, value) {
    return new Promise((resolve, reject) => {
      const data = JSON.stringify(value);
      storage.set({
        key,
        value: data,
        success: () => {
          console.log('Storage save success:', key);
          resolve(true);
        },
        fail: (data, code) => {
          console.error('Storage save failed:', code);
          reject(new Error(`Storage save failed: ${code}`));
        }
      });
    });
  }

  /**
   * 读取数据
   * @param {string} key - 存储键
   * @returns {Promise} 读取结果
   */
  load(key) {
    return new Promise((resolve, reject) => {
      storage.get({
        key,
        success: (data) => {
          try {
            const value = JSON.parse(data);
            resolve(value);
          } catch (e) {
            resolve(data);
          }
        },
        fail: (data, code) => {
          console.error('Storage load failed:', code);
          reject(new Error(`Storage load failed: ${code}`));
        }
      });
    });
  }

  /**
   * 删除数据
   * @param {string} key - 存储键
   * @returns {Promise} 删除结果
   */
  remove(key) {
    return new Promise((resolve, reject) => {
      storage.delete({
        key,
        success: () => {
          console.log('Storage delete success:', key);
          resolve(true);
        },
        fail: (data, code) => {
          console.error('Storage delete failed:', code);
          reject(new Error(`Storage delete failed: ${code}`));
        }
      });
    });
  }

  /**
   * 清空所有数据
   * @returns {Promise} 清空结果
   */
  clear() {
    return new Promise((resolve, reject) => {
      storage.clear({
        success: () => {
          console.log('Storage clear success');
          resolve(true);
        },
        fail: (data, code) => {
          console.error('Storage clear failed:', code);
          reject(new Error(`Storage clear failed: ${code}`));
        }
      });
    });
  }

  /**
   * 获取今日日期字符串
   * @returns {string} 日期字符串 YYYY-MM-DD
   */
  getTodayKey() {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }

  /**
   * 获取本周周数
   * @returns {string} 周数字符串 YYYY-WXX
   */
  getWeekKey() {
    const now = new Date();
    const year = now.getFullYear();
    const startOfYear = new Date(year, 0, 1);
    const days = Math.floor((now - startOfYear) / (24 * 60 * 60 * 1000));
    const weekNumber = Math.ceil((days + startOfYear.getDay() + 1) / 7);
    return `${year}-W${String(weekNumber).padStart(2, '0')}`;
  }

  /**
   * 保存体态记录
   * @param {Object} record - 体态记录
   * @returns {Promise} 保存结果
   */
  async savePostureRecord(record) {
    const todayKey = this.getTodayKey();
    const storageKey = `${STORAGE_KEYS.POSTURE_RECORDS}:${todayKey}`;

    try {
      let records = await this.load(storageKey);
      if (!Array.isArray(records)) {
        records = [];
      }
      records.push(record);
      return await this.save(storageKey, records);
    } catch (error) {
      console.error('Save posture record failed:', error);
      throw error;
    }
  }

  /**
   * 获取今日体态记录
   * @returns {Promise} 体态记录列表
   */
  async getTodayPostureRecords() {
    const todayKey = this.getTodayKey();
    const storageKey = `${STORAGE_KEYS.POSTURE_RECORDS}:${todayKey}`;

    try {
      const records = await this.load(storageKey);
      return Array.isArray(records) ? records : [];
    } catch (error) {
      console.error('Get posture records failed:', error);
      return [];
