import { POSTURE_TYPES, SCORE_PENALTY, SCORE_BONUS } from '../constants';
import storageManager from './storage';

// 统计计算器
class StatsCalculator {
  /**
   * 计算体态评分
   * @param {Array} reminders - 提醒记录
   * @param {number} focusMinutes - 专注时长（分钟）
   * @returns {number} 评分
   */
  calculateScore(reminders, focusMinutes) {
    let score = 100;

    // 扣分项
    reminders.forEach(reminder => {
      const penalty = SCORE_PENALTY[reminder.type] || 0;
      score -= penalty;
    });

    // 加分项
    if (focusMinutes >= 60) {
      score += SCORE_BONUS.focus60;
    } else if (focusMinutes >= 30) {
      score += SCORE_BONUS.focus30;
    }

    // 确保分数在0-100之间
    return Math.max(0, Math.min(100, Math.round(score)));
  }

  /**
   * 计算体态分布
   * @param {Array} records - 体态记录
   * @returns {Object} 体态分布
   */
  calculatePostureDistribution(records) {
    const distribution = {
      [POSTURE_TYPES.NORMAL]: 0,
      [POSTURE_TYPES.HEAD_DOWN]: 0,
      [POSTURE_TYPES.HUNCHBACK]: 0,
      [POSTURE_TYPES.TILT]: 0,
      [POSTURE_TYPES.SHAKE]: 0
    };

    records.forEach(record => {
      if (distribution.hasOwnProperty(record.type)) {
        distribution[record.type] += record.duration || 1;
      }
    });

    // 计算百分比
    const total = Object.values(distribution).reduce((a, b) => a + b, 0);
    if (total > 0) {
      Object.keys(distribution).forEach(key => {
        distribution[key] = Math.round((distribution[key] / total) * 100);
      });
    }

    return distribution;
  }

  /**
   * 更新今日统计
   * @param {Object} params - 参数
   * @returns {Promise} 更新后的统计
   */
  async updateTodayStats(params) {
    const { reminders = [], focusMinutes = 0, postureRecords = [] } = params;

    try {
      // 获取现有统计
      const existingStats = await storageManager.getTodayStats();

      // 计算新的统计
      const newReminderCount = existingStats.reminderCount + reminders.length;
      const newFocusMinutes = existingStats.focusMinutes + focusMinutes;

      // 计算评分
      const allReminders = [
        ...Array(existingStats.reminderCount).fill({ type: POSTURE_TYPES.NORMAL }),
        ...reminders
      ];
      const totalScore = this.calculateScore(allReminders, newFocusMinutes);

      // 计算体态分布
      const postureDistribution = this.calculatePostureDistribution(postureRecords);

      // 构建新的统计对象
      const newStats = {
        date: storageManager.getTodayKey(),
        totalScore: totalScore,
        focusMinutes: newFocusMinutes,
        focusSessions: existingStats.focusSessions + (focusMinutes > 0 ? 1 : 0),
        reminderCount: newReminderCount,
        postureDistribution: postureDistribution
      };

      // 保存统计
      await storageManager.saveDailyStats(newStats);

      return newStats;
    } catch (error) {
      console.error('Update today stats failed:', error);
      throw error;
    }
  }

  /**
   * 获取今日统计摘要
   * @returns {Promise} 统计摘要
   */
  async getTodaySummary() {
    try {
      const stats = await storageManager.getTodayStats();
      const records = await storageManager.getTodayPostureRecords();

      return {
        score: stats.totalScore,
        focusMinutes: stats.focusMinutes,
        focusSessions: stats.focusSessions,
        reminderCount: stats.reminderCount,
        postureDistribution: stats.postureDistribution,
        recordCount: records.length
      };
    } catch (error) {
      console.error('Get today summary failed:', error);
      return {
        score: 0,
        focusMinutes: 0,
        focusSessions: 0,
        reminderCount: 0,
        postureDistribution: {},
        recordCount: 0
      };
    }
  }

  /**
   * 获取周统计摘要
   * @returns {Promise} 周统计摘要
   */
  async getWeeklySummary() {
    try {
      const weeklyStats = await storageManager.getWeeklyStats();

      // 计算平均分
      const totalScore = weeklyStats.reduce((sum, day) => sum + day.totalScore, 0);
      const avgScore = Math.round(totalScore / 7);

      // 计算总专注时长
      const totalFocusMinutes = weeklyStats.reduce((sum, day) => sum + day.focusMinutes, 0);

      // 计算总提醒次数
      const totalReminders = weeklyStats.reduce((sum, day) => sum + day.reminderCount, 0);

      // 计算趋势（与前一天相比）
      const todayScore = weeklyStats[6].totalScore;
      const yesterdayScore = weeklyStats[5].totalScore;
      const trend = todayScore - yesterdayScore;

      return {
        avgScore,
        totalFocusMinutes,
        totalReminders,
        trend,
        dailyStats: weeklyStats
      };
    } catch (error) {
      console.error('Get weekly summary failed:', error);
      return {
        avgScore: 0,
        totalFocusMinutes: 0,
        totalReminders: 0,
        trend: 0,
        dailyStats: []
      };
    }
  }

  /**
   * 生成改善建议
   * @param {Object} stats - 统计数据
   * @returns {Array} 建议列表
   */
  generateSuggestions(stats) {
    const suggestions = [];

    // 基于评分的建议
    if (stats.score < 70) {
      suggestions.push('建议增加休息频率，每30分钟起身活动一下');
    } else if (stats.score < 80) {
      suggestions.push('继续保持，注意保持正确坐姿');
    } else {
      suggestions.push('体态表现优秀，继续保持！');
    }

    // 基于专注时长的建议
    if (stats.focusMinutes < 60) {
      suggestions.push('可以尝试延长专注时间，提高工作效率');
    } else if (stats.focusMinutes > 180) {
      suggestions.push('长时间专注后记得适当休息');
    }

    // 基于提醒次数的建议
    if (stats.reminderCount > 5) {
      suggestions.push('提醒次数较多，建议调整坐姿习惯');
    } else if (stats.reminderCount === 0 && stats.focusMinutes > 0) {
      suggestions.push('没有收到提醒，体态保持得很好！');
    }

    return suggestions;
  }

  /**
   * 格式化专注时长
   * @param {number} minutes - 分钟数
   * @returns {string} 格式化后的字符串
   */
  formatFocusDuration(minutes) {
    if (minutes < 60) {
      return `${minutes}分钟`;
    }
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return mins > 0 ? `${hours}小时${mins}分钟` : `${hours}小时`;
  }

  /**
   * 格式化时长（毫秒）
   * @param {number} ms - 毫秒数
   * @returns {string} 格式化后的字符串
   */
  formatDuration(ms) {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);

    if (hours > 0) {
      return `${hours}小时${minutes % 60}分钟`;
    }
    if (minutes > 0) {
      return `${minutes}分钟${seconds % 60}秒`;
    }
    return `${seconds}秒`;
  }

  /**
   * 获取评分等级
   * @param {number} score - 评分
   * @returns {Object} 等级信息
   */
  getScoreLevel(score) {
    if (score >= 90) {
      return { level: '优秀', color: '#4CAF50', emoji: '🏆' };
    }
    if (score >= 80) {
      return { level: '良好', color: '#2196F3', emoji: '👍' };
    }
    if (score >= 70) {
      return { level: '一般', color: '#FFC107', emoji: '💪' };
    }
    return { level: '较差', color: '#F44336', emoji: '⚠️' };
  }
}

