import share from '@system.share';
import prompt from '@system.prompt';
import { THEME_COLORS } from '../constants';

// 分享工具
class ShareManager {
  /**
   * 生成分享卡片数据
   * @param {Object} stats - 统计数据
   * @returns {Object} 卡片数据
   */
  generateShareCard(stats) {
    const { score, focusMinutes, reminderCount, suggestions } = stats;

    // 计算连续优秀天数（模拟数据）
    const consecutiveDays = score >= 80 ? 3 : 0;

    return {
      title: '今日体态报告',
      score: score,
      scoreLevel: this.getScoreLevel(score),
      focusDuration: this.formatDuration(focusMinutes),
      reminderCount: reminderCount,
      consecutiveDays: consecutiveDays,
      suggestions: suggestions.slice(0, 2),
      appName: 'PostureGuard',
      appSlogan: '健康生活，从好姿势开始'
    };
  }

  /**
   * 获取评分等级
   * @param {number} score - 评分
   * @returns {Object} 等级信息
   */
  getScoreLevel(score) {
    if (score >= 90) {
      return { level: '优秀', color: THEME_COLORS.primary, emoji: '🏆' };
    }
    if (score >= 80) {
      return { level: '良好', color: '#2196F3', emoji: '👍' };
    }
    if (score >= 70) {
      return { level: '一般', color: '#FFC107', emoji: '💪' };
    }
    return { level: '较差', color: '#F44336', emoji: '⚠️' };
  }

  /**
   * 格式化时长
   * @param {number} minutes - 分钟数
   * @returns {string} 格式化后的字符串
   */
  formatDuration(minutes) {
    if (minutes < 60) {
      return `${minutes}分钟`;
    }
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return mins > 0 ? `${hours}小时${mins}分钟` : `${hours}小时`;
  }

  /**
   * 生成分享文本
   * @param {Object} cardData - 卡片数据
   * @returns {string} 分享文本
   */
  generateShareText(cardData) {
    const lines = [
      `📊 ${cardData.title}`,
      '',
      `🏆 体态评分: ${cardData.score}分 (${cardData.scoreLevel.level})`,
      `⏱️ 专注时长: ${cardData.focusDuration}`,
      `💪 连续优秀: ${cardData.consecutiveDays}天`,
      '',
      `🎯 改善目标: 保持正确坐姿`,
      '',
      `───`,
      `${cardData.appName} - ${cardData.appSlogan}`
    ];

    return lines.join('\n');
  }

  /**
   * 分享到系统
   * @param {Object} cardData - 卡片数据
   * @returns {Promise} 分享结果
   */
  async shareToSystem(cardData) {
    try {
      const shareText = this.generateShareText(cardData);

      const result = await new Promise((resolve, reject) => {
        share.share({
          type: 'text',
          data: shareText,
          success: (data) => {
            console.log('Share success:', data);
            resolve(data);
          },
          fail: (data, code) => {
            console.error('Share failed:', code);
            reject(new Error(`Share failed: ${code}`));
          }
        });
      });

      return result;
    } catch (error) {
      console.error('Share to system failed:', error);
      throw error;
    }
  }

  /**
   * 显示分享预览
   * @param {Object} cardData - 卡片数据
   * @returns {Promise} 用户操作结果
   */
  showSharePreview(cardData) {
    return new Promise((resolve) => {
      prompt.showDialog({
        title: '分享体态报告',
        message: this.generateShareText(cardData),
        buttons: [
          {
            text: '取消',
            color: '#999999',
            action: () => {
              resolve({ cancelled: true });
            }
          },
          {
            text: '分享',
            color: THEME_COLORS.primary,
            action: () => {
              resolve({ cancelled: false, action: 'share' });
            }
          }
        ]
      });
    });
  }

  /**
   * 完整的分享流程
   * @param {Object} stats - 统计数据
   * @returns {Promise} 分享结果
   */
  async shareReport(stats) {
    try {
      // 生成卡片数据
      const cardData = this.generateShareCard(stats);

      // 显示预览
      const previewResult = await this.showSharePreview(cardData);

      if (previewResult.cancelled) {
        return { success: false, reason: 'cancelled' };
      }

      // 执行分享
      const shareResult = await this.shareToSystem(cardData);

      return { success: true, result: shareResult };
    } catch (error) {
      console.error('Share report failed:', error);
      return { success: false, reason: error.message };
    }
  }

  /**
   * 复制到剪贴板
   * @param {Object} cardData - 卡片数据
   * @returns {Promise} 复制结果
   */
  async copyToClipboard(cardData) {
    try {
      const shareText = this.generateShareText(cardData);

      // 注意：openvela快应用可能不支持剪贴板API
      // 这里使用分享功能代替
      const result = await this.shareToSystem(cardData);

      return { success: true, result };
    } catch (error) {
      console.error('Copy to clipboard failed:', error);
      return { success: false, reason: error.message };
    }
  }
}

